int handle_far_return(struct x86_emulate_ctxt *ctxt)
{
    unsigned long new_eip, new_cs;
    int rc;

    rc = ctxt->emulate_pop(ctxt, &new_eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = ctxt->emulate_pop(ctxt, &new_cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    if (!ctxt->ops->get_segment(ctxt, &ctxt->src, new_cs, VIRT_CS)) {
        ctxt->error_code = X86EMUL_UNHANDLEABLE;
        return X86EMUL_EXCEPTION;
    }

    if (ctxt->src.dpl > ctxt->cpl) {
        ctxt->error_code = X86EMUL_UNHANDLEABLE;
        return X86EMUL_EXCEPTION;
    }

    ctxt->eip = new_eip;
    ctxt->regs->cs = new_cs;

    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    unsigned long eip, cs;
    int rc;

    rc = ctxt->ops->read_stack(ctxt, &cs, 0);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = ctxt->ops->read_stack(ctxt, &eip, sizeof(cs));
    if (rc != X86EMUL_CONTINUE)
        return rc;

    if (!ctxt->ops->is_canon(ctxt, cs))
        return X86EMUL_UNHANDLEABLE;

    if ((ctxt->mode != X86EMUL_MODE_REAL) &&
        (ctxt->ops->get_segment(ctxt, &cs, NULL, 0, NULL, VCPU_SREG_CS) ||
         (ctxt->ops->get_cpl(ctxt) > 3)))
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = eip;
    return ctxt->ops->set_segment(ctxt, cs, 0, 0, VCPU_SREG_CS);
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    unsigned long eip, cs;
    int rc;

    rc = emulate_pop(ctxt, &eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = emulate_pop(ctxt, &cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    /* Check for privilege level violations and load CS descriptor */
    if ((ctxt->mode != X86EMUL_MODE_REAL) && ((cs & 3) > (ctxt->cpl & 3)))
        return X86EMUL_EXCEPTION;

    ctxt->regs->eip = eip;
    ctxt->regs->cs = cs;
    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    unsigned long eip, cs;
    int rc;

    rc = ctxt->ops->read_stack(ctxt, &eip, sizeof(eip));
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = ctxt->ops->read_stack(ctxt, &cs, sizeof(cs));
    if (rc != X86EMUL_CONTINUE)
        return rc;

    if (!ctxt->ops->is_protmode(ctxt)) {
        // Real mode handling
        ctxt->eip = eip;
        ctxt->regs->cs = cs;
    } else {
        // Protected mode handling
        struct desc_struct *desc;
        desc = ctxt->ops->get_segment_descriptor(ctxt, cs);
        if (!desc || (desc->type & 0x1f) < 8) {
            return X86EMUL_EXCEPTION;
        }

        if ((desc->dpl < (ctxt->cpl & 0x3)) && (ctxt->ops->is_currently_calling(ctxt)))
            return X86EMUL_EXCEPTION;

        ctxt->eip = eip;
        ctxt->regs->cs = cs;
    }

    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    unsigned long eip, cs;

    if (emulate_pop(ctxt, &eip))
        return X86EMUL_CONTINUE;

    if (emulate_pop(ctxt, &cs))
        return X86EMUL_CONTINUE;

    if (!ctxt->ops->get_segment(ctxt, &cs, 0)) {
        if (cs & 1) {
            /* Check privilege level violations */
            if ((cs >> 4) & 3) {
                return X86EMUL_UNHANDLEABLE;
            }
        }

        ctxt->regs->eip = eip;
        ctxt->regs->cs = cs;
    }

    return X86EMUL_CONTINUE;
}
